#!/usr/bin/env python3
"""Embed resources/splash.png into src/ofxOceanodeSplashImage.h.

The startup splash artwork is compiled into the addon so host apps need no
resource copied into their bundle. Run after replacing resources/splash.png:

    python3 scripts/embed_splash.py
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "resources" / "splash.png"
TARGET = ROOT / "src" / "ofxOceanodeSplashImage.h"


def main():
    data = SOURCE.read_bytes()
    lines = [
        "// Generated by scripts/embed_splash.py from resources/splash.png. Do not edit.",
        "#pragma once",
        "#include <cstddef>",
        "",
        f"inline constexpr std::size_t ofxOceanodeSplashPngSize = {len(data)};",
        "inline constexpr unsigned char ofxOceanodeSplashPng[] = {",
    ]
    for start in range(0, len(data), 24):
        lines.append("    " + ",".join(str(byte) for byte in data[start:start + 24]) + ",")
    lines += ["};", ""]
    TARGET.write_text("\n".join(lines))
    print(f"{TARGET.relative_to(ROOT)}: {len(data)} bytes embedded")


if __name__ == "__main__":
    main()
